import 'package:flutter/material.dart';import '../../../../Core/Utils/Extensions/widget_extension.dart';import '../../../../Core/Storage/Local/local_storage_service.dart';import '../../../../Core/Utils/Widget/custom_sliver_grid_builder.dart';import '../Home/data/models/product_preview_entities.dart';class FavoriteScreen extends StatefulWidget {  const FavoriteScreen({super.key});  @override  State<FavoriteScreen> createState() => _FavoriteScreenState();}class _FavoriteScreenState extends State<FavoriteScreen> {  List<ProductPreviewEntities> model = [];  @override  void initState() {    model = ProductStorageService.getAllProducts();    super.initState();  }  @override  Widget build(BuildContext context) {    return [      BuildCustomGridBuilder(        model: model,        loading: model.isEmpty,      ),    ].styledAppPages(withAll: true);  }}